import {renderView,section,button,list} from '../ui/view.js';import {PublishService} from '../services/publish-service.js';import {BookService} from './literary-services-book-service.js';import {el} from './literary-core-dom.js';import {notify} from './literary-core-notifications.js';
export async function publishView(){const booksR=await BookService.list(),books=booksR.books||[],body=document.createDocumentFragment();body.append(section('Portable project',[button('Export project JSON package',async()=>{const r=await PublishService.exportProject({});notify(r.message||'Project export complete.');}),button('Create backup',async()=>{const r=await PublishService.backup({});notify(r.message||'Backup complete.');})]));body.append(section('Interactive HTML books',[list(books,b=>{const a=el('article',{},[el('strong',{text:b.title||'Untitled Book'}),el('p',{text:'Exports an HTML reader with chapter JSON, page navigation, theme settings, and optional page-flip sound.'})]);a.append(button('Export HTML book',async()=>{await BookService.exportHtml({bookId:b.id});notify('HTML book export complete.');}));return a;},{empty:'Create a book in Book Builder before exporting an interactive edition.'})]));body.append(section('Accessibility in published web editions',[el('p',{text:'The publishing model carries responsive layout, text sizing, contrast/reduced-motion hooks, keyboard navigation, read-aloud state, and a sound toggle so page effects remain optional.'})]));renderView('Publish Center',{description:'Export usable, portable LiteraryFriend project packages, backups, and interactive book editions.',body});}
